"""保存用户直接使用的三份文件，并建立本地合集播放器。"""
from pathlib import Path
import hashlib, html, json, shutil

R=Path(__file__).resolve().parents[1];V=R/'production/user-script-v2';O=V/'release-speed1p3'
m=json.loads((O/'delivery-manifest.json').read_text());D=R/'delivery/前10集合集_1.3倍_字幕版';D.mkdir(parents=True,exist_ok=True)
video=R/m['video'];cover=O/'小红书横屏封面-v1.png';title=(O/'小红书标题.txt').read_text().strip();body=(O/'小红书发布正文.txt').read_text().strip()
shutil.copy2(video,D/video.name);shutil.copy2(cover,D/'小红书横屏封面.png');(D/'小红书标题文案.txt').write_text('标题：'+title+'\n\n正文：\n'+body+'\n')
files=[D/video.name,D/'小红书横屏封面.png',D/'小红书标题文案.txt']
(O/'delivery-files.json').write_text(json.dumps([{'path':str(p.resolve()),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size} for p in files],ensure_ascii=False,indent=2)+'\n')
data=json.dumps(m['chapters'],ensure_ascii=False)
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>末世囤货 · 前10集完整合集</title><style>body{margin:auto;padding:28px;max-width:1120px;background:#101418;color:#eee;font:16px system-ui}h1{font-size:25px}p{line-height:1.8;color:#bdc6ce}video,img{width:100%;border-radius:12px;background:#000}video{max-height:70vh}button,a{border:0;border-radius:7px;padding:10px 14px;background:#314550;color:white;text-decoration:none;cursor:pointer}#chapters{display:flex;flex-wrap:wrap;gap:9px;margin:16px 0}#status{margin:12px 0;color:#c9dca2}.files{display:flex;flex-wrap:wrap;gap:12px;margin:22px 0}pre{white-space:pre-wrap;line-height:1.9;font:16px system-ui;background:#1a232a;padding:22px;border-radius:12px}</style><h1>末世囤货：我的安全屋住满了女神</h1><p>前10集完整合集 · 14分19秒 · Chinese_worker_male · 保音调1.3倍 · 已烧录无标点中文字幕</p><video id="film" controls preload="metadata" playsinline poster="小红书横屏封面-v1.png" src="VIDEO_NAME"></video><div id="status">点击播放完整合集</div><button id="play">播放完整合集</button> <button id="ending">片尾</button><div id="chapters"></div><div class="files"><a download href="VIDEO_NAME">保存视频</a><a download href="小红书横屏封面-v1.png">保存封面</a><a download href="小红书发布正文.txt">发布正文</a></div><h2>推荐标题</h2><pre>TITLE_TEXT</pre><h2>发布文案</h2><pre>BODY_TEXT</pre><h2>横屏封面</h2><img src="小红书横屏封面-v1.png" alt="末世来了 我还在涮火锅"><script>const v=document.querySelector('#film');v.playbackRate=1;const status=document.querySelector('#status');v.addEventListener('playing',()=>status.textContent='正在播放完整合集');v.addEventListener('ended',()=>status.textContent='完整合集播放完成');v.addEventListener('error',()=>status.textContent='播放错误 '+v.error?.code);document.querySelector('#play').onclick=()=>{v.currentTime=0;v.playbackRate=1;v.play()};document.querySelector('#ending').onclick=()=>{v.currentTime=Math.max(0,v.duration-12);v.playbackRate=1;v.play()};const chapters=CHAPTER_DATA;for(const c of chapters){const b=document.createElement('button');b.textContent='第'+Number(c.episode.slice(2))+'集 '+c.title;b.onclick=()=>{v.currentTime=c.start_frame/30;v.playbackRate=1;v.play()};document.querySelector('#chapters').appendChild(b)}</script></html>'''
page=page.replace('VIDEO_NAME',html.escape(video.name)).replace('TITLE_TEXT',html.escape(title)).replace('BODY_TEXT',html.escape(body)).replace('CHAPTER_DATA',data)
(O/'index.html').write_text(page)
status=json.loads((V/'status.json').read_text());status.update(final_shot_images=m['images'],planned_final_shots=m['images'],release_state='RENDERED_FULL_DECODE_PASS_PLAYBACK_PENDING',complete_episode_videos=10,merged_video=str((D/video.name).relative_to(R)),cover=str((D/'小红书横屏封面.png').relative_to(R)),copy=str((D/'小红书标题文案.txt').relative_to(R)),text_changes=0,subtitles={'status':'PASS_533_BURNED_IN_PUNCTUATION_FREE','source_text_changes':0},video='PASS_10_EPISODES_AND_MERGED_FULL_DECODE')
(V/'status.json').write_text(json.dumps(status,ensure_ascii=False,indent=2)+'\n')
print('DELIVERY',D.resolve(),flush=True)
